package dev.veltraph.client.metrics;
import dev.veltraph.client.core.*;import dev.veltraph.client.config.AutoSellMode;import dev.veltraph.client.inventory.selling.SellingAcknowledgment;import java.math.BigDecimal;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
final class SellingReceiptProjectionTest {
 static final class Owner extends AbstractModule{Owner(){super("seller","seller",ModuleCategory.MISC);}public void onEnable(){}public void onDisable(){}public void onTick(){}}
 final ModuleManager manager=new ModuleManager();final Owner owner=new Owner();final FinancialOutcomeBindings.Scope scope=new FinancialOutcomeBindings.Scope(new Object(),new Object(),new Object());final AtomicReference<List<SellingAcknowledgment>> receipts=new AtomicReference<>(List.of());final List<FinancialOutcomeBindings.Outcome> events=new ArrayList<>();final FinancialOutcomeBindings.Sink sink=new FinancialOutcomeBindings.Sink(){public boolean confirmed(String id,boolean expense,BigDecimal amount,long now){events.add(new FinancialOutcomeBindings.Outcome(id,expense,amount,scope));return true;}public boolean confirmed(FinancialOutcomeBindings.Outcome o,long now){events.add(o);return true;}};final FinancialOutcomeBindings bridge=new FinancialOutcomeBindings(manager,m->Optional.of(SellingReceiptProjection.binding(m,receipts::get)),()->scope,()->sink,()->true);
 SellingReceiptProjectionTest(){manager.register(owner);manager.enable(owner.id());bridge.afterFreshStart(owner,0);}
 SellingAcknowledgment ack(String id,BigDecimal value,SellingAcknowledgment.Denomination currency,FinancialOutcomeBindings.Scope context,FinancialActionReceipt.Evidence evidence){return new SellingAcknowledgment(id,AutoSellMode.NPC,"exact wheat",9,4,value,BigDecimal.ZERO,value,"Purse",currency,context.player(),context.world(),context.connection(),evidence);}
 SellingAcknowledgment receipt(BigDecimal value,long sequence){return ack(UUID.randomUUID().toString(),value,SellingAcknowledgment.Denomination.COINS,scope,new FinancialActionReceipt.Evidence(menu,2,2+(int)sequence,3+(int)sequence,sequence,"NPC"));}final Object menu=new Object();
 @Test void existingSingleNativeAckRemainsOneOutcomeWithExactEvidence(){var a=receipt(new BigDecimal("12"),1);receipts.set(List.of(a));manager.disable(owner.id());bridge.poll(1);bridge.poll(2);assertEquals(1,events.size());assertEquals(new BigDecimal("12"),events.getFirst().amountOrNull());assertSame(a.evidence(),events.getFirst().receipt().evidence().getFirst());assertSame(owner,events.getFirst().receipt().owner());}
 @Test void twoNativeStepsInOneMenuAreStreamedOnceWhileOwnerStillActive(){var a=receipt(new BigDecimal("12"),1);receipts.set(List.of(a));bridge.poll(1);var b=receipt(new BigDecimal("15"),2);receipts.set(List.of(a,b));bridge.poll(2);bridge.poll(3);assertEquals(List.of(new BigDecimal("12"),new BigDecimal("15")),events.stream().map(FinancialOutcomeBindings.Outcome::amountOrNull).toList());assertNotEquals(events.get(0).id(),events.get(1).id());}
 @Test void finalPollPreservesAllAcknowledgedStepsWhenLaterBatchIsUnknown(){var a=receipt(BigDecimal.ONE,1);var b=receipt(BigDecimal.TEN,2);receipts.set(List.of(a,b));manager.disable(owner.id());bridge.poll(1);assertEquals(2,events.size());manager.enable(owner.id());bridge.afterFreshStart(owner,2);bridge.poll(3);assertEquals(2,events.size(),"Old terminal evidence is excluded on fresh activation");}
 @Test void unknownDenominationHasNoCoinValueAndMissingNativeEvidenceIsIgnored(){var unknown=ack(UUID.randomUUID().toString(),BigDecimal.TEN,SellingAcknowledgment.Denomination.UNKNOWN,scope,new FinancialActionReceipt.Evidence(menu,2,1,2,1,"NPC"));var noEvidence=ack(UUID.randomUUID().toString(),BigDecimal.TEN,SellingAcknowledgment.Denomination.COINS,scope,null);receipts.set(List.of(unknown,noEvidence));bridge.poll(1);assertEquals(1,events.size());assertNull(events.getFirst().amountOrNull());assertEquals(FinancialActionReceipt.Denomination.UNKNOWN,events.getFirst().receipt().denomination());}
 @Test void pendingCancelledOrForeignScopeCannotBecomeIncome(){manager.disable(owner.id());bridge.poll(1);assertTrue(events.isEmpty());manager.enable(owner.id());bridge.afterFreshStart(owner,2);var foreign=new FinancialOutcomeBindings.Scope(new Object(),scope.world(),scope.connection());receipts.set(List.of(ack(UUID.randomUUID().toString(),BigDecimal.TEN,SellingAcknowledgment.Denomination.COINS,foreign,new FinancialActionReceipt.Evidence(menu,2,1,2,1,"NPC"))));bridge.poll(3);assertTrue(events.isEmpty());}
 @Test void acceptedPartialThenCancelKeepsOneAndNeverCreditsPendingQuote(){var first=receipt(new BigDecimal("12"),1);receipts.set(List.of(first));bridge.poll(1);manager.disable(owner.id());bridge.poll(2);bridge.poll(3);assertEquals(1,events.size());assertEquals(first.outcomeId(),events.getFirst().id());assertEquals(new BigDecimal("12"),events.getFirst().amountOrNull());}
}

